BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_family_transition_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,pathway TEXT NOT NULL CHECK(pathway IN('single_parent','divorced','widowed')),remarriage_goal BOOLEAN,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS mission_bridge_childcare_resources(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,city_code TEXT NOT NULL,name TEXT NOT NULL,contact_summary TEXT NOT NULL,verified BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS mission_bridge_family_budgets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,period TEXT NOT NULL,income_total NUMERIC(12,2),essential_total NUMERIC(12,2),support_total NUMERIC(12,2),private BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(private=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_grief_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,emotion TEXT NOT NULL,loss_impact TEXT NOT NULL,support_needed TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_holiday_support_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,occasion TEXT NOT NULL,loneliness_level INTEGER CHECK(loneliness_level BETWEEN 1 AND 5),trusted_contacts JSONB NOT NULL DEFAULT '[]'::jsonb,planned_activity TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_transition_family_activities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,title TEXT NOT NULL,child_stability_goal TEXT NOT NULL,completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS mission_bridge_transition_peer_links(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,peer_user_id TEXT NOT NULL,mutual_consent BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS mission_bridge_transition_referrals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,referral_type TEXT NOT NULL CHECK(referral_type IN('employment','legal','childcare','grief')),verified_provider_id UUID REFERENCES mission_bridge_referral_directory(id),status TEXT NOT NULL DEFAULT 'requested');
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_family_transition_profiles','mission_bridge_childcare_resources','mission_bridge_family_budgets','mission_bridge_grief_logs','mission_bridge_holiday_support_plans','mission_bridge_transition_family_activities','mission_bridge_transition_peer_links','mission_bridge_transition_referrals'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
